Method.Source:
/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "l_forupdate">boolean</param>
/// <returns>NDXUmsatzParameters</returns>
static NDXUmsatzParameters find(boolean l_forupdate = false)
{
    NDXUmsatzParameters parameter;

    parameter.selectForUpdate(l_forupdate);

    select firstonly parameter
    index KeyIdx
    where parameter.key == 0;

    if (!parameter && !parameter.isTmp())
    {
        Company::createParameter(parameter);
    }

    return parameter;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "lastBuildAlliance">utcdatetime</param>
static void setLastBuildAlliance(utcdatetime lastBuildAlliance = DateTimeUtil::utcNow())
{
    NDXUmsatzParameters    parameters;
    ;
    parameters = NDXUmsatzParameters::find(true);
    ttsbegin;
    parameters.lastBuildAlliance = lastBuildAlliance;
    parameters.update();
    ttscommit;
}

